*{box-sizing:border-box} :root{font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#17352b;background:#f3f7f5} body{margin:0;min-height:100vh;background:radial-gradient(circle at top right,#e7f3ec 0,#f3f7f5 42%,#eef4f1 100%);padding:1.25rem} main{max-width:78rem;margin:auto}.topbar{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:.35rem 0 1.5rem}.brand{font-weight:800;letter-spacing:-.02em;color:#124b37;text-decoration:none}.brand small{display:block;color:#789087;font-size:.72rem;font-weight:600;letter-spacing:.08em;text-transform:uppercase}.nav{display:flex;flex-wrap:wrap;gap:.35rem}.nav a{color:#587168;text-decoration:none;padding:.45rem .7rem;border-radius:.55rem;font-size:.9rem}.nav a:hover,.nav a.active{background:#dceee5;color:#176b4d}.card{background:rgba(255,255,255,.92);border:1px solid #dce8e1;border-radius:1rem;padding:1.35rem;margin-bottom:1.35rem;box-shadow:0 10px 28px rgba(26,74,54,.06)}.eyebrow{color:#176b4d;font-size:.74rem;font-weight:800;letter-spacing:.1em;text-transform:uppercase;margin:0 0 .45rem}h1{font-size:clamp(1.7rem,3vw,2.4rem);letter-spacing:-.04em;margin:.15rem 0 .4rem}h2{font-size:1.1rem;margin:.2rem 0 .5rem}.muted{color:#61776d}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(15rem,1fr));gap:1.25rem;margin-bottom:.25rem}.tile{display:block;border:1px solid #cfe1d7;border-radius:.85rem;padding:1.2rem;text-decoration:none;color:#17352b;background:#fff;transition:transform .15s ease,box-shadow .15s ease,border-color .15s ease}.tile:hover{transform:translateY(-2px);border-color:#8dbba3;box-shadow:0 10px 22px rgba(26,74,54,.1)}.tile p{margin-bottom:0}.button{display:inline-block;background:#176b4d;color:#fff;padding:.65rem .9rem;border-radius:.55rem;text-decoration:none;font-weight:700;font-size:.9rem;border:0;cursor:pointer}.button:hover{background:#0f573c}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:44rem}th{color:#6b8177;font-size:.74rem;letter-spacing:.06em;text-transform:uppercase}th,td{text-align:left;padding:.85rem .7rem;border-bottom:1px solid #e4eee8;vertical-align:top}tbody tr:hover{background:#f7fbf8}td a{color:#176b4d;font-weight:700;text-decoration:none}.notice{background:#e9f7ee;border:1px solid #c8e4d2;padding:.75rem;border-radius:.55rem}.status{display:inline-block;background:#e7f4ec;color:#176b4d;border-radius:99px;padding:.25rem .55rem;font-size:.78rem;font-weight:800}.actions{display:flex;align-items:center;justify-content:space-between;gap:1rem;flex-wrap:wrap}label{display:block;margin-top:1rem;font-weight:700;color:#315447}input,select{width:100%;box-sizing:border-box;margin-top:.4rem;padding:.7rem .75rem;border:1px solid #b8cdc1;border-radius:.55rem;background:#fff;color:#17352b;font:inherit}input:focus,select:focus{outline:3px solid #cce8d8;border-color:#176b4d}.readonly{background:#eef4f0;color:#61776d}.error{color:#a32929;background:#fff1f0;border:1px solid #f0c8c4;border-radius:.55rem;padding:.7rem}.error ul{margin:.25rem 0;padding-left:1.2rem}.form-actions{display:flex;gap:.65rem;align-items:center;flex-wrap:wrap;margin-top:1.25rem}.back{color:#176b4d;font-weight:700;text-decoration:none}@media(max-width:640px){body{padding:.8rem}.topbar{align-items:flex-start;flex-direction:column;padding-bottom:1.25rem}.nav{width:100%}.nav a{padding:.4rem .5rem}.card{padding:1.05rem;margin-bottom:1rem}.grid{gap:1rem}}
